import React from 'react';
import { NavLink } from 'react-router-dom';

import {
  FiHome,
  FiImage,
  FiVideo,
  FiBookOpen,
  FiClipboard,
  FiStar,
  FiAward,
  FiMessageSquare,
  FiSettings,
  FiX,
  FiLayers,
  FiHeart,
  FiUser,
} from 'react-icons/fi';

import { useLanguage } from '../../contexts/LanguageContext';
import logo from './SC ACADEMY new.png';

// ==========================================
// ADMIN SIDEBAR
// ==========================================

const AdminSidebar = ({
  isOpen = false,
  onClose,
}) => {
  const { t, language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  // ==========================================
  // MENU ITEMS
  // ==========================================

  const menuItems = [
    {
      key: 'admin.dashboard',
      name: t('admin.dashboard') || (isKhmer ? 'ផ្ទាំងគ្រប់គ្រង' : 'Dashboard'),
      path: '/',
      icon: FiHome,
    },
    {
      key: 'admin.gallery',
      name: t('admin.gallery') || (isKhmer ? 'វិចិត្រសាល' : 'Gallery'),
      path: '/gallery',
      icon: FiImage,
    },
    {
      key: 'admin.videos',
      name: t('admin.videos') || (isKhmer ? 'វីដេអូ' : 'Videos'),
      path: '/videos',
      icon: FiVideo,
    },
    {
      key: 'admin.courses',
      name: t('admin.courses') || (isKhmer ? 'វគ្គសិក្សា' : 'Courses'),
      path: '/courses',
      icon: FiBookOpen,
    },
    {
      key: 'admin.schools',
      name: t('admin.schools') || (isKhmer ? 'សាលារៀន' : 'Schools'),
      path: '/schools',
      icon: FiLayers,
    },
    {
      key: 'admin.alumni',
      name: t('admin.alumni') || (isKhmer ? 'អតីតសិស្ស' : 'Alumni'),
      path: '/alumni',
      icon: FiAward,
    },
    {
      key: 'admin.charity',
      name: t('admin.charity') || (isKhmer ? 'សប្បុរសធម៌' : 'Charity'),
      path: '/charity',
      icon: FiHeart,
    },
    {
      key: 'admin.testimonials',
      name: t('admin.testimonials') || (isKhmer ? 'មតិសិស្ស' : 'Testimonials'),
      path: '/testimonials',
      icon: FiStar,
    },
    {
      key: 'admin.messages',
      name: t('admin.messages') || (isKhmer ? 'សារទំនាក់ទំនង' : 'Messages'),
      path: '/messages',
      icon: FiMessageSquare,
    },
    {
      key: 'admin.settings',
      name: t('admin.settings') || (isKhmer ? 'ការកំណត់' : 'Settings'),
      path: '/settings',
      icon: FiSettings,
    },
    {
      key: 'admin.profile',
      name: isKhmer ? 'ប្រវត្តិរូប Admin' : 'Admin Profile',
      path: '/profile',
      icon: FiUser,
    },
  ];

  // ==========================================
  // CLOSE MOBILE SIDEBAR
  // ==========================================

  const handleClose = () => {
    if (typeof onClose === 'function') {
      onClose();
    }
  };

  return (
    <>
      {/* MOBILE OVERLAY */}
      {isOpen && (
        <div
          className="fixed inset-0 z-40 bg-blue-950/70 backdrop-blur-[2px] lg:hidden"
          onClick={handleClose}
          aria-hidden="true"
        />
      )}

      {/* SIDEBAR */}
      <aside
        className={`fixed top-0 left-0 z-50 w-[270px] h-screen bg-gradient-to-b from-[#071a3d] via-[#0b2d63] to-[#071a3d] text-white border-r border-white/10 shadow-xl transition-transform duration-300 ease-in-out lg:translate-x-0 ${
          isOpen ? 'translate-x-0' : '-translate-x-full'
        } ${isKhmer ? 'font-khmer' : 'font-english'}`}
      >
        {/* BRAND HEADER */}
        <div className="h-[84px] px-4 flex items-center justify-between border-b border-white/10">
          <NavLink
            to="/"
            onClick={handleClose}
            className="flex items-center gap-3 min-w-0"
          >
            <div className="w-12 h-12 flex items-center justify-center flex-shrink-0 bg-white rounded-full p-1.5 shadow-md">
              <img
                src={logo}
                alt="SC Academy"
                className="w-full h-full object-contain"
              />
            </div>
            <div className="min-w-0">
              <h2 className="text-base font-extrabold text-white leading-tight truncate">
                SC ACADEMY
              </h2>
              <p className="text-[10px] text-blue-300 font-semibold tracking-wider uppercase mt-0.5">
                Admin Panel
              </p>
            </div>
          </NavLink>

          {/* MOBILE CLOSE BUTTON */}
          <button
            type="button"
            onClick={handleClose}
            className="w-9 h-9 flex items-center justify-center rounded-xl bg-white/10 text-white/80 hover:bg-white/20 hover:text-white transition lg:hidden"
          >
            <FiX size={18} />
          </button>
        </div>

        {/* NAVIGATION LINKS */}
        <nav className="h-[calc(100vh-84px)] overflow-y-auto px-3 py-4 space-y-1 custom-scrollbar">
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <NavLink
                key={item.path}
                to={item.path}
                onClick={handleClose}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3.5 py-2.5 rounded-xl text-xs font-semibold transition-all duration-200 ${
                    isActive
                      ? 'bg-[#2563EB] text-white shadow-md shadow-blue-500/20 translate-x-1'
                      : 'text-white/70 hover:bg-white/10 hover:text-white'
                  }`
                }
              >
                <Icon size={17} className="flex-shrink-0" />
                <span className="truncate">{item.name}</span>
              </NavLink>
            );
          })}

          {/* SYSTEM STATUS CARD */}
          <div className="mt-6 p-3.5 bg-white/5 border border-white/10 rounded-xl">
            <div className="flex items-center gap-2">
              <div className="relative flex-shrink-0">
                <span className="block w-2 h-2 bg-green-400 rounded-full" />
                <span className="absolute inset-0 w-2 h-2 bg-green-400 rounded-full animate-ping opacity-50" />
              </div>
              <span className="text-[11px] font-semibold text-white">
                {t('admin.systemOnline') || (isKhmer ? 'ប្រព័ន្ធដំណើរការធម្មតា' : 'System Online')}
              </span>
            </div>
            <p className="text-[10px] text-white/40 mt-1.5 leading-4">
              SC Academy Administration v2.0
            </p>
          </div>
        </nav>
      </aside>
    </>
  );
};

export default AdminSidebar;
